var u = GameState.get_unit("U_INTERCESSOR_SQUAD_A")
var t = GameState.get_unit("U_REPULSOR_A")
return u.models[0].get("position", null) == null and "U_INTERCESSOR_SQUAD_A" in t.get("transport_data", {}).get("embarked_units", [])

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_real_log_file_path(), FileAccess.READ)
var n := 0
while f != null and not f.eof_reached():
	var l := f.get_line()
	if l.contains("[ERROR"):
		n += 1
		print("[sm11e-m4c] debug-log ERROR: ", l)
return n
